write('lesson-ui.js','''(()=>{'use strict';const activity=document.querySelector('#activity'),source=document.querySelector('#source'),L=window.LESSON;function go(h){window.speechSynthesis?.cancel();location.hash=h;window.scrollTo?.({top:0,behavior:'instant'})}function enhance(){const state=window.LessonEngine.state();if(state.position.view==='read'){const p=state.position.p,t=L.paragraphTasks[p-1];if(t){const next=document.querySelector('#nextPara');next.textContent='完成本段问题';next.onclick=()=>go('task-'+t)}if(!activity.querySelector('.word-support')){const box=document.createElement('section');box.className='word-support';box.innerHTML='<b>本段词语</b><p>点击词语查看释义；需要复习时再收藏。</p>';for(const[w,v]of Object.entries(window.LESSON_WORDS)){if(v.paragraph!==p||w==='奢侈')continue;const b=document.createElement('button');b.className='word';b.dataset.word=w;b.textContent=w;box.append(b)}activity.querySelector('.word-add-row').before(box)}}if(state.position.view==='task'){const t=L.tasks[state.position.task];const next=document.querySelector('#nextTask');const map={goods:5,logistics:7,culture:8};if(map[t.id]){next.textContent='继续读第'+map[t.id]+'段';next.onclick=()=>go('paragraph-'+map[t.id])}if(!activity.querySelector('.sequence-nav')){const nav=document.createElement('div');nav.className='sequence-nav';nav.innerHTML='<a class="btn" href="#paragraph-'+t.focus[0]+'">回到本段图文</a>';activity.querySelector('.task-footer').before(nav)}if(t.id==='goods'&&!activity.querySelector('.oral-probe')){const d=document.createElement('details');d.className='oral-probe';d.innerHTML='<summary>完成后口头想一想</summary><p>除了货物，还有什么随着贸易传播？请回看第一、第四段。</p>';activity.querySelector('.question-source').before(d)}}}const obs=new MutationObserver(()=>{obs.disconnect();enhance();watch()});function watch(){obs.observe(activity,{childList:true});obs.observe(source,{childList:true})}enhance();watch()})();''')
write('comics.html',page('完整漫画回读','''<main class="home comic-pages"><a class="btn" href="index.html">返回主页</a><h1>完整漫画回读</h1><p>以下四页沿用原图。读后可以连起来回顾；作答依据以课文原句为准。</p>'''+''.join(f'<figure><img src="assets/comic{i}.png" alt="《新加坡与世界的联系》漫画第{i}页" loading="lazy"><figcaption>原图第{i}页</figcaption></figure>' for i in range(1,5))+'<section class="card"><h2>完整课文</h2>'+''.join('<h3>第'+str(i+1)+'段 · '+h(L['paragraphLabels'][i])+'</h3><p class="kai">'+h(x)+'</p>' for i,x in enumerate(L['paragraphs']))+'</section></main>'))
