write('teacher.html',page('教师专区','''<main class="home notes"><a class="btn" href="index.html">返回课程主页</a><h1>教师流程与资源</h1><p>中二高级华文 · 单元六 · 生活空间 · 1课时（按50分钟设计）</p>'''+resources+'''<h2>本课目标</h2><ol>'''+''.join('<li>'+h(s)+'</li>' for s in brief['goals'])+'''</ol><h2>课堂流程</h2><table><thead><tr><th>环节</th><th>分钟</th><th>课堂行动</th></tr></thead><tbody>'''+rows+'''</tbody></table><p>教师示范第1题如何区分“货物”与“用途”；第2题让学生自主取证、写完整答案；第3题共同找“不但……也……”；第4题独立点选；开放题先独立写再分享。四项词语释义只做一次。</p><h2>整合与取舍</h2><p>旧活动保留“从一盘鸡饭想世界联系”的切入点，改为两条有来源的资料，限时3分钟。取消六国猜配对、缺少依据的产地判断和额外小测。课本四道理解题、四项词语释义和开放题均已保留，统一放在本课入口。</p><p>本课使用教材原有数字与历史表述：“600多个港口”和“2014年愿景”用于理解教材，不作为最新统计或全部已完成的现实结论。</p><h2>图文对应</h2><p>8个教学段号按课文自然段顺序编排，小标题不另算一段。四页漫画原文件不变，网页展示对应画格。参观情境与综合回顾画格只用于导入或回顾，不充当原文证据。</p><h2>作答与记录</h2><p>客观题首次错误后先给定位提示，等5秒再试；再次作答后可查看解释。第2题和开放题仅作结构完成检查与答案对照，由教师判断内容，页面不自动给主观题分数。这里列出的分值是教师建议量表，不是课本官方分值。</p><p>学习记录保留首次作答、尝试和订正。词语本沿用华文通共享记录，可按年级、单元、课文筛选；词语释义与例句随词保存，已掌握词也可复习。离线文件的记录独立于网站，换设备时需分别导出学习记录和词语本。</p>'''+answers+'''<h2>资料与旧版参考</h2><ul>'''+''.join(f'<li><a href="{h(s["url"])}" target="_blank" rel="noopener">{h(s["title"])}</a>：{h(s["purpose"])}</li>' for s in brief['sources'] if 'url'in s)+'''</ul></main>''','<script src="pack.js"></script>'))
write('projection.html',page('在线投影','''<main class="projection" id="projection"><div class="toolbar"><a class="btn" href="teacher.html">教师专区</a><button id="prev">上一页</button><select id="slideSelect" aria-label="选择投影片"></select><button id="next">下一页</button><button id="full">全屏</button><span id="count"></span></div><div class="slide-stage"><img id="slide" alt=""></div><details><summary>教师提示</summary><p id="notes"></p></details></main>''','<script src="projection.js"></script>'))
write('projection.js','''fetch('slides/slides.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(slides=>{let i=Math.max(0,Math.min(slides.length-1,(parseInt(location.hash.slice(1))||1)-1));const el=id=>document.getElementById(id),sel=el('slideSelect');slides.forEach((s,n)=>{const o=document.createElement('option');o.value=n;o.textContent=(n+1)+' · '+s.title;sel.append(o)});function show(){const s=slides[i];el('slide').src=s.image;el('slide').alt=s.title;el('notes').textContent=s.notes;el('count').textContent=(i+1)+' / '+slides.length;sel.value=i;el('prev').disabled=i===0;el('next').disabled=i===slides.length-1;history.replaceState(null,'','#'+(i+1))}el('prev').onclick=()=>{i=Math.max(0,i-1);show()};el('next').onclick=()=>{i=Math.min(slides.length-1,i+1);show()};sel.onchange=()=>{i=+sel.value;show()};el('full').onclick=()=>{const x=el('projection');if(document.fullscreenElement)document.exitFullscreen();else x.requestFullscreen?.()};document.onkeydown=e=>{if(e.target.matches('select,button,a'))return;if(e.key==='ArrowRight')el('next').click();if(e.key==='ArrowLeft')el('prev').click()};show()}).catch(()=>{document.getElementById('notes').textContent='投影片加载失败，请刷新或下载PPT。'});''')
write('pack.js','''document.getElementById('downloadPackage').onclick=async function(){const status=document.getElementById('packageStatus');this.disabled=true;try{const m=await fetch('downloads/package-manifest.json').then(r=>{if(!r.ok)throw Error();return r.json()});const parts=[];for(let i=0;i<m.parts.length;i++){status.textContent='下载中 '+(i+1)+' / '+m.parts.length;const r=await fetch('downloads/'+m.parts[i].file);if(!r.ok)throw Error();const b=await r.arrayBuffer();const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');if(digest!==m.parts[i].sha256)throw Error('资料校验失败');parts.push(b)}const blob=new Blob(parts,{type:'application/zip'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=m.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='完整配套已准备好，请保存。'}catch(e){status.textContent='下载未完成，请重试。'+(e.message==='资料校验失败'?e.message:'')}finally{this.disabled=false}};''')
