p=REPO/'index.html';s=p.read_text();m=re.search(r'const DATA=(\{.*?\});',s);data=json.loads(m.group(1));unit=next(x for x in data['2']['texts'] if x['title']=='单元六');item=unit['items'][0];assert item['title']=='生活空间 · 新加坡与世界的联系';item.update(url='du/textbook/2hcl/unit6/xinjiapo-yu-shijie/index.html',note='课文图文、互动学习、词语本与教师配套。');s=s[:m.start(1)]+json.dumps(data,ensure_ascii=False,separators=(',',':'))+s[m.end(1):];p.write_text(s)
